export const toolWorkflows=Object.freeze(entries);
export function getToolWorkflow(category,requested){
 if(requested===false)return null;
 const key=typeof requested==='string'&&Object.hasOwn(toolWorkflows,requested)?requested:category;
 return Object.hasOwn(toolWorkflows,key)?toolWorkflows[key]:null;
}
